//! Seam 2: the Vault, through its public interface only.
//!
//! Starter vectors were generated by running BitWindow's own `DeriveStarter`
//! (LayerTwo-Labs/drivechain-frontends @ 6f72ee2a, sidechain-orchestrator/wallet/keygen.go,
//! go-bip32 v1.0.0, go-bip39 v1.1.0), so one Master Mnemonic yields the same Starter in both wallets.
use bitcoin::base58;
use ecx_vault::{canonical_mnemonic, l1_account_key, master_mnemonic_from_entropy, starter, stretch_password, KdfParams};

const ABANDON: &str = "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";

#[test]
fn slot_24_starter_without_passphrase_matches_bitwindow() {
    assert_eq!(
        starter(ABANDON, "", 24).unwrap(),
        "buyer citizen congress doll secret merry denial law live wait pass drive"
    );
}

#[test]
fn slot_24_starter_with_passphrase_matches_bitwindow() {
    assert_eq!(
        starter(ABANDON, "TREZOR", 24).unwrap(),
        "raw sister combine impact penalty improve soap power tomato topic frog flip"
    );
}

#[test]
fn starters_for_other_slots_and_masters_match_bitwindow() {
    let vectors = [
        (ABANDON, "", 0, "myth destroy anchor erosion give style space already ticket oval mask people"),
        (ABANDON, "", 9, "tower plug offer music panda loan earn rather burger giant junior grief"),
        (ABANDON, "", 256, "barely trumpet spike absurd rude sniff subway entry milk cricket defense item"),
        (ABANDON, "TREZOR", 0, "stable element slender lab limb between action club stone demise during moon"),
        (ABANDON, "TREZOR", 9, "wealth wrestle axis vessel dutch much oil year gesture oil snake protect"),
        (ABANDON, "TREZOR", 256, "clip between imitate dutch fall reopen bicycle art bundle tourist phone latin"),
        (
            "legal winner thank year wave sausage worth useful legal winner thank yellow",
            "",
            24,
            "blush cream bullet drive index disease noble east target dice put rate",
        ),
    ];
    for (master, passphrase, slot, expected) in vectors {
        assert_eq!(starter(master, passphrase, slot).unwrap(), expected, "slot {slot}, passphrase {passphrase:?}");
    }
}

#[test]
fn a_master_mnemonic_typed_with_capitals_and_extra_spaces_gives_the_same_starter() {
    let sloppy = "  Abandon abandon ABANDON abandon\tabandon abandon abandon abandon abandon abandon abandon   about\n";
    assert_eq!(
        starter(sloppy, "", 24).unwrap(),
        "buyer citizen congress doll secret merry denial law live wait pass drive"
    );
}

// Create: the caller supplies the randomness (the module has no RNG of its own).
#[test]
fn a_new_master_mnemonic_is_12_words_from_the_callers_16_bytes_of_entropy() {
    assert_eq!(master_mnemonic_from_entropy(&[0u8; 16]).unwrap(), ABANDON);
    assert_eq!(
        master_mnemonic_from_entropy(&[0x7f; 16]).unwrap(),
        "legal winner thank year wave sausage worth useful legal winner thank yellow"
    );
}

#[test]
fn creating_with_too_little_entropy_fails() {
    assert!(master_mnemonic_from_entropy(&[0u8; 15]).is_err());
    assert!(master_mnemonic_from_entropy(&[]).is_err());
}

// Import: what the user typed, checked and put in the one form the Vault stores.
#[test]
fn an_imported_phrase_is_stored_in_canonical_form() {
    let typed = " ABANDON abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon  About ";
    assert_eq!(canonical_mnemonic(typed).unwrap(), ABANDON);
}

#[test]
fn importing_a_phrase_with_a_bad_checksum_or_unknown_word_fails() {
    let bad_checksum = "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon";
    assert!(canonical_mnemonic(bad_checksum).is_err());
    let unknown_word = "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon xyzzy";
    assert!(canonical_mnemonic(unknown_word).is_err());
    assert!(canonical_mnemonic("").is_err());
}

// Encryption at rest: the password is stretched with Argon2id into the vault key.
// Vector cross-checked against Go golang.org/x/crypto/argon2 v0.43.0 IDKey (same parameters).
#[test]
fn the_password_is_stretched_with_argon2id() {
    let key = stretch_password(b"password", b"somesaltsomesalt", KdfParams { m_kib: 65536, t: 3, p: 1 }).unwrap();
    assert_eq!(hex(&key), "7664ad4ba1a3c999fcdd0991ffc2270f78302d2383233db5e7befc85d1bb1819");
}

#[test]
fn stretching_rejects_a_salt_shorter_than_8_bytes() {
    assert!(stretch_password(b"password", b"short", KdfParams::DEFAULT).is_err());
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

/// BIP84's own vector (bip-0084.mediawiki): "abandon … about"'s account 0 key, printed as `zprv`.
const BIP84_ACCOUNT_ZPRV: &str =
    "zprvAdG4iTXWBoARxkkzNpNh8r6Qag3irQB8PzEMkAFeTRXxHpbF9z4QgEvBRmfvqWvGp42t42nvgGpNgYSJA9iefm1yYNZKEm7z6qUWCroSQnE";

#[test]
fn the_l1_account_key_is_bip84s_account_0_key_with_its_origin() {
    let mut bytes = base58::decode_check(BIP84_ACCOUNT_ZPRV).unwrap();
    bytes[..4].copy_from_slice(&[0x04, 0x88, 0xad, 0xe4]); // the same key, `xprv` version bytes
    assert_eq!(l1_account_key(ABANDON, "").unwrap(), format!("[73c5da0a/84h/0h/0h]{}", base58::encode_check(&bytes)));
}

#[test]
fn the_l1_account_key_depends_on_the_passphrase_and_is_no_starter() {
    let key = l1_account_key(ABANDON, "").unwrap();
    assert_ne!(l1_account_key(ABANDON, "TREZOR").unwrap(), key);
    for slot in [0, 24, 84] {
        assert_ne!(starter(ABANDON, "", slot).unwrap(), key);
    }
}
